gFq(){return"\u0939\u091f\u093e\u090f\u0902"},
gOb(){return"\u0915\u094b\u0908 \u092b\u093c\u094b\u0928 \u0928\u0939\u0940\u0902"},
gOo(){return"\u092a\u093f\u0928 \u0930\u0940\u0938\u0947\u091f \u0915\u0930\u0947\u0902"},
